document.addEventListener("DOMContentLoaded",()=>{const e=[{name:"Rabari",description:"Known for the use of mirrors in various shapes (round, triangular, square) and heavily decorated with chain stitches. Commonly uses vibrant colors like red, maroon, and yellow."},{name:"Ahir",description:"Characterized by round mirrors surrounded by intricate floral and bird motifs, typically done in chain stitch and herringbone stitch."},{name:"Jat",description:"Geometric patterns featuring closely clustered stitches with tiny mirrors, known for its dense and rigid structure, primarily found in Garasia Jat embroidery."},{name:"Mutwa",description:"Features extremely fine stitching with tiny mirrors. Mutwa embroidery includes a variety of styles like Mukko, Khareek, and Suf, known for delicate and precise needlework."}],t=[{name:"Chain Stitch (Sankli)",region:"Kutch General",description:"A series of looped stitches forming a chain-like pattern, extensively used to outline motifs and fill spaces in Ahir and Rabari embroidery."},{name:"Buttonhole Stitch",region:"Rabari",description:"Commonly used to fix mirrors securely onto the fabric, creating a decorative border around the glass."},{name:"Herringbone Stitch",region:"Ahir",description:"A crossed stitch used for filling larger areas of motifs, adding texture and depth to the embroidered patterns."},{name:"Darning Stitch",region:"Suf / Mutwa",description:"Counted thread embroidery done from the back of the fabric, creating precise geometric and symmetrical designs without outlining."}],n=[{name:"Peacock (Mor)",significance:"A common motif symbolizing beauty, grace, and the onset of monsoons. Frequently used in Ahir and Rabari embroidery."},{name:"Parrot (Popat)",significance:"Symbolizes love and passion. Often depicted in pairs facing each other."},{name:"Elephant (Hathi)",significance:"Represents strength, royalty, and prosperity. Commonly found in borders and central panels."},{name:"Mango (Keri) / Paisley",significance:"Symbol of fertility and prosperity, widely used across all styles of Kutch embroidery."},{name:"Floral Patterns (Phool)",significance:"Various flowers are used to depict the beauty of nature and life's blossoming."}],i=document.getElementById("regional-styles-container");i&&e.forEach(e=>{const t=document.createElement("div");t.className="style-row",t.innerHTML=`\n                <h3 style="color: var(--primary-gold); font-size: 1.5rem; margin-bottom: 10px;">${e.name}</h3>\n                <p style="color: var(--text-muted); line-height: 1.6;">${e.description}</p>\n            `,i.appendChild(t)});const r=document.getElementById("details-modal"),a=document.getElementById("modal-title"),o=document.getElementById("modal-region"),s=document.getElementById("modal-desc"),d=document.getElementById("close-modal");function c(e,t,n){a.textContent=e,o.textContent=t?`Region/Significance: ${t}`:"",s.textContent=n,r.classList.add("active")}d&&d.addEventListener("click",()=>{r.classList.remove("active")}),r&&r.addEventListener("click",e=>{e.target===r&&r.classList.remove("active")});const l=document.getElementById("stitch-gallery");l&&t.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.innerHTML=`\n                <h3>${e.name}</h3>\n                <p style="color: var(--text-muted); font-size: 0.9rem;">Click to view details</p>\n            `,t.addEventListener("click",()=>{c(e.name,e.region,e.description)}),l.appendChild(t)});const m=document.getElementById("motif-gallery");m&&n.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.innerHTML=`\n                <h3>${e.name}</h3>\n                <p style="color: var(--text-muted); font-size: 0.9rem;">Click to view significance</p>\n            `,t.addEventListener("click",()=>{c(e.name,"",e.significance)}),m.appendChild(t)})});